'use client';

// The server action is defined in a server file and imported
// here; the compiler turns it into an RPC stub.
import { createPost } from '@/app/actions';

export default function NewPostForm() {
  // Plain HTML form semantics: the action runs on the server,
  // revalidates the cache, and the returned Flight payload
  // updates the UI — all in one round trip.
  return (
    <form action={createPost}>
      <input name="title" placeholder="Post title" />
      <button type="submit">Create</button>
    </form>
  );
}

